func validateImportedBundle(root, repoKey string) error {
	data, err := os.ReadFile(filepath.Join(root, exportManifestFileName))
	if err != nil {
		return fmt.Errorf("bundle missing manifest: %w", err)
	}
	var manifest exportManifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		return fmt.Errorf("parse bundle manifest: %w", err)
	}
	if manifest.RepoKey != "" && manifest.RepoKey != repoKey {
		return fmt.Errorf("bundle repo_key %q does not match current repo %q", manifest.RepoKey, repoKey)
	}
	if manifest.Sources == nil || manifest.Sources.Semantic == nil {
		return errors.New("bundle manifest missing semantic source")
	}
	snapshotPath := manifest.Sources.Semantic.SnapshotPath
	if snapshotPath == "" {
		return errors.New("bundle manifest missing semantic snapshot_path")
	}
	clean := filepath.Clean(filepath.FromSlash(snapshotPath))
	if strings.HasPrefix(clean, ".."+string(filepath.Separator)) || filepath.IsAbs(clean) || !strings.HasPrefix(filepath.ToSlash(clean), semanticDirName+"/") {
		return fmt.Errorf("bundle semantic snapshot_path is unsafe: %s", snapshotPath)
	}
	info, err := os.Stat(filepath.Join(root, clean))
	if err != nil {
		return fmt.Errorf("bundle missing referenced semantic snapshot: %w", err)
	}
	if info.IsDir() {
		return errors.New("bundle semantic snapshot_path points to a directory")
	}
	return nil
}

func rejectRemoteBundlePath(path string) error {
	lower := strings.ToLower(strings.TrimSpace(path))
	for _, prefix := range []string{"http://", "https://", "s3://", "git+ssh://"} {
		if strings.HasPrefix(lower, prefix) {
			return fmt.Errorf("bundle path must be local: %s", path)
		}
	}
	if strings.HasPrefix(lower, "file://") && !strings.HasPrefix(lower, "file:///") {
		return fmt.Errorf("bundle file URL must not include a hostname: %s", path)
	}
	return nil
}

func validateBundleEntry(header *tar.Header) error {
	if header.Typeflag != tar.TypeReg && header.Typeflag != 0 {
		return fmt.Errorf("bundle entry must be a regular file: %s", header.Name)
	}
	if strings.HasPrefix(header.Name, "/") || strings.Contains(header.Name, "..") {
		return fmt.Errorf("unsafe bundle path: %s", header.Name)
	}
	clean := filepath.Clean(filepath.FromSlash(header.Name))
	if clean == "." || strings.HasPrefix(clean, ".."+string(filepath.Separator)) {
		return fmt.Errorf("unsafe bundle path: %s", header.Name)
	}
	if clean != exportManifestFileName && !strings.HasPrefix(filepath.ToSlash(clean), semanticDirName+"/") {
		return fmt.Errorf("bundle entry outside allowed paths: %s", header.Name)
	}
	return nil
}

